Widget chartToRun() {
  ChartOptions chartOptions = const ChartOptions();
  var chartData = RandomChartData.generated(chartOptions: chartOptions);
  var lineChartContainer = LineChartTopContainer(
    chartData: chartData,
    xContainerLabelLayoutStrategy: null,
  );
